deluge_script:
if(input.Service != null)
										{
											input.Display_Name_Service = input.Service.Service_Name;
										}

if(input.Item != null)
										{
											// Display Name
											input.Display_Name_Item = ifnull(input.Item.Item_Name,"") + " - " + ifnull(input.Item.SKU,"");
											// Unit of Measure (your Item display field)
											input.Unit_Of_Measure = input.Item.Display_Name_Base_Unit_Of_Measure;
											// Rate from Average Cost
											input.Rate = ifnull(input.Item.Default_Cost,0);
											// Line Total
											input.Line_Total = ifnull(input.Rate,0) * ifnull(input.Quantity_Needed,0);
										}
										else
										{
											// Clear fields if Item is removed
											input.Display_Name_Item = "";
											input.Unit_Of_Measure = null;
											input.Rate = 0;
											input.Line_Total = 0;
											input.Quantity_Needed = 0;
										}

//DISABLE FIELDS
										disable Display_Name_Service;
										disable Display_Name_Item;
										disable Unit_Of_Measure;
										disable Rate;
										disable Line_Total;
										//HIDE FIELDS
										hide Display_Name_Service;
										hide Display_Name_Item;

if(input.Service == null)
										{
											alert "Please select a Service.";
											cancel submit;
										}
										if(input.Item == null)
										{
											alert "Please select an Item.";
											cancel submit;
										}
										if(input.Quantity_Needed == null || input.Quantity_Needed <= 0)
										{
											alert "Quantity Needed must be greater than 0.";
											cancel submit;
										}

if(input.Service != null)
										{
											input.Display_Name_Service = input.Service.Service_Name;
										}
										else
										{
											input.Display_Name_Service = "";
										}

if(input.Task != null)
										{
											input.Display_Name_Task = input.Task.Task_Name;
											input.Description = input.Task.Description;
										}
										else
										{
											input.Display_Name_Task = "";
											input.Description = "";
										}
										if(input.Task != null)
										{
											input.Display_Name_Task = input.Task.Task_Name;
										}
										else
										{
											input.Display_Name_Task = "";
										}

for each  itemRow in input.Service_Items
										{
											if(itemRow.Display_Name_Service == null || itemRow.Display_Name_Service == "" && input.Service_Name != null)
											{
												itemRow.Display_Name_Service=input.Service_Name;
											}
										}

total_items_cost = 0;
										for each  itemRow in input.Service_Items
										{
											// 1

total_items_cost = 0;
										for each  itemRow in input.Service_Items
										{
											// Recalculate the row line total (safe even if Quantity didn’t change)
											itemRow.Line_Total=ifnull(itemRow.Rate,0) * ifnull(itemRow.Quantity_Needed,0);
											// Sum into parent
											total_items_cost = total_items_cost + ifnull(itemRow.Line_Total,0);
										}
										// Update parent totals
										input.Total_Cost = total_items_cost;
										// Optional: if you want Rate to follow Total_Cost
										// input.Rate = total_items_cost;

for each  itemRow in input.Service_Tasks
										{
											if(itemRow.Display_Name_Service == null || itemRow.Display_Name_Service == "" && input.Service_Name != null)
											{
												itemRow.Display_Name_Service=input.Service_Name;
											}
										}

for each  taskRow in input.Service_Tasks
										{
											if(taskRow.Task != null)
											{
												// Auto-fill Display Name
												taskRow.Display_Name_Task=ifnull(taskRow.Task.Task_Name,"");
												// Auto-fill Description
												taskRow.Description=ifnull(taskRow.Task.Description,"");
											}
											else
											{
												// Clear fields if task removed
												taskRow.Display_Name_Task="";
												taskRow.Description="";
											}
										}

//DISABLE FIELDS
										disable Total_Cost;
										//SERVICE ITEMS
										disable Service_Items.Display_Name_Service;
										disable Service_Items.Display_Name_Item;
										disable Service_Items.Unit_Of_Measure;
										disable Service_Items.Rate;
										disable Service_Items.Line_Total;
										//SERVICE TASKS
										disable Service_Tasks.Display_Name_Service;
										disable Service_Tasks.Display_Name_Task;
										disable Service_Tasks.Description;
										//HIDE FIELDS
										//SERVICE ITEMS
										hide Service_Items.Display_Name_Service;
										hide Service_Items.Display_Name_Item;
										//SERVICE TASKS
										hide Service_Tasks.Display_Name_Service;
										hide Service_Tasks.Display_Name_Task;
										u = thisapp.audit.getLoginAuditInfo();
										input.User_Name = u.get("name");
										input.User_Email = u.get("email");
										input.User_Role = u.get("role");
										hide Back_End;

//DISABLE FIELDS
										disable Display_Name_Service;
										disable Display_Name_Task;
										disable Description;
										//HIDE FIELDS
										hide Display_Name_Service;
										hide Display_Name_Task;

if(input.Service != null)
										{
											input.Rate = ifnull(input.Service.Rate,0);
										}
										else
										{
											input.Rate = 0;
										}

// DISABLE FIELDS
										disable Payment_Status;
										disable In_Store_Stage;
										disable Rate;
										disable Display_Name_Sales_Voucher;
										// Lock delivery fields only when Picked is ticked
										if(input.Picked == true)
										{
											disable Picked;
											disable Pick_Up_Date;
											disable In_Store_Stage;
										}
										else
										{
											// Always lock pick up date (system controlled)
											disable Pick_Up_Date;
										}

if(input.Customer != null)
										{
											input.Display_Name_Customer = ifnull(input.Customer.Customer_Name,"") + " - " + ifnull(input.Customer.Phone_Number,"");
										}
										else
										{
											input.Display_Name_Customer = "";
										}

if(input.Customer != null)
										{
											input.Phone_Number = input.Customer.Phone_Number;
											input.WhatsApp_Number = input.Customer.WhatsApp_Number;
											input.Display_Name_Customer = input.Customer.Customer_Name + " - " + input.Customer.Phone_Number;
										}
										for each  shoeRow in input.Shoe_Services
										{
											shoeRow.Display_Name_Customer=input.Display_Name_Customer;
										}

if(input.Sales_Voucher != null)
										{
											// Autofill display name from the selected Tracking Number record
											input.Display_Name_Sales_Voucher = ifnull(input.Sales_Voucher.Sales_Voucher_Number,"");
											input.Display_Name_Customer = input.Sales_Voucher.Display_Name_Customer;
										}
										else
										{
											// Clear if removed
											input.Display_Name_Sales_Voucher = "";
											input.Display_Name_Customer = "";
										}

for each  shoeRow in input.Shoe_Services
										{
											if(shoeRow.Service != null)
											{
												// Only set Rate if it's empty/zero (prevents overwriting old pricing)
												if(shoeRow.Rate == null || shoeRow.Rate == 0)
												{
													shoeRow.Rate=ifnull(shoeRow.Service.Rate,0);
												}
											}
											else
											{
												shoeRow.Rate=0;
											}
										}
										// Recalculate Sub Total as the sum of all row rates
										subTotal = 0;
										for each  shoeRow in input.Shoe_Services
										{
											subTotal = subTotal + ifnull(shoeRow.Rate,0);
										}
										input.Sub_Total = subTotal;

total_allocated = 0;
										lineNo = 0;
										for each  allocRow in input.Payment_Receipt_Details
										{
											// Line number
											lineNo = lineNo + 1;
											allocRow.Line_Number=lineNo;
											// Display name payment
											allocRow.Display_Name_Voucher=input.Payment_Receipt_Number;
											// Sum allocations
											total_allocated = total_allocated + ifnull(allocRow.Amount_Allocated,0);
										}
										for each  shoeRow in input.Payment_Receipt_Details
										{
											shoeRow.Display_Name_Voucher=input.Payment_Receipt_Number;
											shoeRow.Customer=input.Display_Name_Customer;
										}
										// Update parent totals
										input.Total_Amount_Allocated = total_allocated;
										input.Total_Amount_Not_Allocated = ifnull(input.Total_Amount_Received,0) - total_allocated;
										// Allocation Status Logic
										if(input.Total_Amount_Allocated == 0)
										{
											input.Payment_Receipt_Voucher_Status = "Unallocated";
										}
										else if(input.Total_Amount_Not_Allocated > 0)
										{
											input.Payment_Receipt_Voucher_Status = "Partially Allocated";
										}
										else
										{
											input.Payment_Receipt_Voucher_Status = "Fully Allocated";
										}

total_allocated = 0;
										lineNo = 0;
										for each  allocRow in input.Payment_Receipt_Details
										{
											// Line number
											lineNo = lineNo + 1;
											allocRow.Line_Number=lineNo;
											// Display name payment
											allocRow.Display_Name_Voucher=input.Payment_Receipt_Number;
											// Sum allocations
											total_allocated = total_allocated + ifnull(allocRow.Amount_Allocated,0);
										}
										// Update parent totals
										input.Total_Amount_Allocated = total_allocated;
										input.Total_Amount_Not_Allocated = ifnull(input.Total_Amount_Received,0) - total_allocated;
										// Allocation Status Logic
										if(input.Total_Amount_Allocated == 0)
										{
											input.Payment_Receipt_Voucher_Status = "Unallocated";
										}
										else if(input.Total_Amount_Not_Allocated > 0)
										{
											input.Payment_Receipt_Voucher_Status = "Partially Allocated";
										}
										else
										{
											input.Payment_Receipt_Voucher_Status = "Fully Allocated";
										}

// =====================================================
										// PAYMENT RECEIPT VOUCHER — FULL VALIDATION
										// =====================================================
										errors = "";
										// =====================================================
										// 1. PAYMENT RECEIPT DATE
										// =====================================================
										if(input.Payment_Receipt_Date == null)
										{
											input.Payment_Receipt_Date = zoho.currenttime;
										}
										if(input.Payment_Receipt_Date.toDate() > zoho.currentdate)
										{
											errors = errors + "\n• Payment Receipt Date cannot be in the future.";
										}
										// =====================================================
										// 2. RECEIVING ACCOUNT AND ACCOUNT TYPE
										// =====================================================
										account_type = "";
										if(input.Receiving_Account == null)
										{
											errors = errors + "\n• Please select the Receiving Account.";
										}
										else
										{
											if(input.Receiving_Account.Account_Type != null)
											{
												account_type = ifnull(input.Receiving_Account.Account_Type.Account_Type_Name,"").trim();
											}
											input.Account_Type = account_type;
											if(account_type == "")
											{
												errors = errors + "\n• Account Type could not be determined from the selected Receiving Account.";
											}
											else if(account_type == "Cash Account")
											{
												if(input.Payment_Receipt_Number == null || input.Payment_Receipt_Number.trim() == "")
												{
													errors = errors + "\n• The cash receipt number was not generated.";
												}
											}
											else if(account_type == "Mobile Money Account")
											{
												if(input.Payment_Receipt_Number == null || input.Payment_Receipt_Number.trim() == "")
												{
													errors = errors + "\n• Please enter the Mobile Money transaction ID.";
												}
											}
											else
											{
												errors = errors + "\n• Unsupported Account Type: " + account_type + ".";
											}
										}
										// =====================================================
										// 3. AMOUNT RECEIVED
										// =====================================================
										if(ifnull(input.Total_Amount_Received,0.0) <= 0)
										{
											errors = errors + "\n• Total Amount Received must be greater than zero.";
										}
										// =====================================================
										// 4. CUSTOMER
										// =====================================================
										if(input.Customer == null)
										{
											errors = errors + "\n• Please select the Customer.";
										}
										// =====================================================
										// 5. BLOCK SUBMISSION
										// =====================================================
										if(errors != "")
										{
											alert errors;
											cancel submit;
										}

// Generate only if empty (prevents changing during edit)
										if(input.Payment_Receipt_Number == null || input.Payment_Receipt_Number == "")
										{
											gen = Code_Generator[Prefix == "PAA" && Status == "Active"];
											if(gen == null)
											{
												alert "No ACTIVE Code Generator found for prefix PAA. Please set it up.";
											}
											else
											{
												nextNum = ifnull(gen.Next_Number,1);
												// Block if greater than 9999
												if(nextNum > 9999)
												{
													alert "Payment Number limit reached (PAA9999). Please create a new prefix.";
													// optional: cancel submit if you're running this on create/submit
												}
												else
												{
													// Pad to 4 digits
													formattedNum = nextNum.toString();
													if(nextNum < 10)
													{
														formattedNum = "000" + formattedNum;
													}
													else if(nextNum < 100)
													{
														formattedNum = "00" + formattedNum;
													}
													else if(nextNum < 1000)
													{
														formattedNum = "0" + formattedNum;
													}
													input.Payment_Receipt_Number = gen.Prefix + formattedNum;
													// increment
													gen.Next_Number=nextNum + 1;
												}
											}
										}
										gen = Code_Generator[Prefix == "PAA" && Status == "Active"];
										if(gen != null && ifnull(gen.Next_Number,1) > 10000)
										{
											alert "Cannot create new Payment. Payment numbers are capped at PAA9999.";
											cancel submit;
										}

grandTotal = ifnull(input.Grand_Total,0);
										paid = ifnull(input.Amount_Paid,0);
										statusVal = "Unpaid";
										if(paid <= 0)
										{
											statusVal = "Unpaid";
										}
										else if(paid < grandTotal)
										{
											statusVal = "Partially Paid";
										}
										else
										{
											statusVal = "Paid";
										}
										for each  shoeRow in input.Shoe_Services
										{
											shoeRow.Payment_Status=statusVal;
										}

// =====================================================
										// 1️⃣ REQUIRED FIELD VALIDATIONS
										// =====================================================
										if(input.Voucher == null)
										{
											alert "Please select a voucher.";
											cancel submit;
										}
										if(input.Customer == null)
										{
											alert "Please select a Customer.";
											cancel submit;
										}
										if(input.Shoe_Services.isEmpty())
										{
											alert "Please add at least one record in Items Dropped.";
											cancel submit;
										}
										rowNo = 0;
										for each  shoeRow in input.Shoe_Services
										{
											rowNo = rowNo + 1;
											if(shoeRow.Shoe_Type == null)
											{
												alert "Items Dropped (Row " + rowNo + "): Shoe Type is required.";
												cancel submit;
											}
											if(shoeRow.Brand == null)
											{
												alert "Items Dropped (Row " + rowNo + "): Brand is required.";
												cancel submit;
											}
											if(shoeRow.Color == null)
											{
												alert "Items Dropped (Row " + rowNo + "): Color is required.";
												cancel submit;
											}
											if(shoeRow.Condition_Level == null || shoeRow.Condition_Level == "")
											{
												alert "Items Dropped (Row " + rowNo + "): Condition Level is required.";
												cancel submit;
											}
											if(shoeRow.Shoe_Image == null || shoeRow.Shoe_Image.toString().trim() == "")
											{
												alert "Items Dropped (Row " + rowNo + "): Shoe Image is required.";
												cancel submit;
											}
											if(shoeRow.Service == null)
											{
												alert "Items Dropped (Row " + rowNo + "): Service is required.";
												cancel submit;
											}
											if(shoeRow.Storage_Container == null)
											{
												alert "Items Dropped (Row " + rowNo + "): Storage Container is required.";
												cancel submit;
											}
										}
										// =====================================================
										// 2️⃣ TRACKING NUMBER GENERATION
										// =====================================================
										if(input.Sales_Voucher_Number == null || input.Sales_Voucher_Number == "")
										{
											gen = Code_Generator[Prefix == "TAA" && Status == "Active"];
											if(gen == null)
											{
												alert "No ACTIVE Code Generator found for prefix TAA.";
												cancel submit;
											}
											else
											{
												nextNum = ifnull(gen.Next_Number,1);
												if(nextNum > 9999)
												{
													alert "Tracking Number limit reached (TAA9999).";
													cancel submit;
												}
												else
												{
													formattedNum = nextNum.toString();
													if(nextNum < 10)
													{
														formattedNum = "000" + formattedNum;
													}
													else if(nextNum < 100)
													{
														formattedNum = "00" + formattedNum;
													}
													else if(nextNum < 1000)
													{
														formattedNum = "0" + formattedNum;
													}
													input.Sales_Voucher_Number = gen.Prefix + formattedNum;
													gen.Next_Number=nextNum + 1;
												}
											}
										}
										// =====================================================
										// 3️⃣ TOTAL CALCULATIONS
										// =====================================================
										subTotal = 0;
										for each  shoeRow in input.Shoe_Services
										{
											subTotal = subTotal + ifnull(shoeRow.Rate,0);
										}
										input.Sub_Total = subTotal;
										grandTotal = ifnull(input.Sub_Total,0) - ifnull(input.Discount_Amount,0);
										if(grandTotal < 0)
										{
											grandTotal = 0;
										}
										input.Grand_Total = grandTotal;
										balance = ifnull(input.Grand_Total,0) - ifnull(input.Amount_Paid,0);
										if(balance < 0)
										{
											balance = 0;
										}
										input.Balance_Due = balance;
										// =====================================================
										// 4️⃣ PAYMENT STATUS
										// =====================================================
										paid = ifnull(input.Amount_Paid,0);
										statusVal = "Unpaid";
										if(paid <= 0)
										{
											statusVal = "Unpaid";
										}
										else if(paid < grandTotal)
										{
											statusVal = "Partially Paid";
										}
										else
										{
											statusVal = "Paid";
										}
										for each  shoeRow in input.Shoe_Services
										{
											shoeRow.Display_Name_Sales_Voucher=input.Sales_Voucher_Number;
											shoeRow.Payment_Status=statusVal;
										}
										// =====================================================
										// 5. PICKED VALIDATION + UPDATE PRODUCTION DETAILS
										// =====================================================
										for each  shoe_row in input.Shoe_Services
										{
											if(shoe_row.Picked == true)
											{
												tracking_number = ifnull(shoe_row.Display_Name_Sales_Voucher,input.Sales_Voucher_Number);
												production_rec = Production_Details[Tracking_Number == tracking_number && Line_Number == shoe_row.Line_Number];
												if(production_rec.ID == null)
												{
													alert "Production Details record was not found for shoe line " + shoe_row.Line_Number + ".";
													cancel submit;
												}
												if(production_rec.In_Store_Stage != "Ready" && production_rec.In_Store_Stage != "Picked")
												{
													alert "Shoe line " + shoe_row.Line_Number + " cannot be picked because its production stage is " + ifnull(production_rec.In_Store_Stage,"Not Defined") + ".";
													cancel submit;
												}
												shoe_row.In_Store_Stage="Picked";
												if(shoe_row.Pick_Up_Date == null)
												{
													shoe_row.Pick_Up_Date=zoho.currenttime;
												}
												production_rec.In_Store_Stage="Picked";
											}
										}
										// =====================================================
										// 6. AUTO CLOSE SALES VOUCHER
										// =====================================================
										if(input.Shoe_Services.isEmpty())
										{
											if(input.Status != "Closed")
											{
												input.Status = "Open";
											}
										}
										else
										{
											all_picked = true;
											for each  shoe_row in input.Shoe_Services
											{
												if(shoe_row.Picked != true || shoe_row.In_Store_Stage != "Picked")
												{
													all_picked = false;
													break;
												}
											}
											if(all_picked == true)
											{
												input.Status = "Closed";
											}
											else if(input.Status != "Closed")
											{
												input.Status = "Open";
											}
										}

if(input.Sales_Voucher != null)
										{
											Payment_Document = "Sales Voucher";
											input.Display_Name_Invoice_Voucher = input.Sales_Voucher.Sales_Voucher_Number;
											input.Customer = input.Sales_Voucher.Display_Name_Customer;
											input.Amount_Due = ifnull(input.Sales_Voucher.Balance_Due,0);
											input.Balance_Due = ifnull(input.Amount_Due,0) - ifnull(input.Amount_Allocated,0);
										}
										else
										{
											input.Display_Name_Invoice_Voucher = "";
											input.Customer = "";
											input.Amount_Due = 0;
											input.Balance_Due = 0;
										}

// Recalculate allocated total from the subform
										allocatedTotal = 0;
										for each  allocRow in input.Payment_Receipt_Details
										{
											allocatedTotal = allocatedTotal + ifnull(allocRow.Amount_Allocated,0);
										}
										// If payment amount is reduced below what's already allocated, block it
										if(ifnull(input.Total_Amount_Received,0) < allocatedTotal)
										{
											alert "Payment Amount cannot be less than the total Amount Cleared in allocations.";
											// Set it back to the allocated total to keep consistency
											input.Total_Amount_Received = allocatedTotal;
										}
										// Update parent totals
										input.Total_Amount_Allocated = allocatedTotal;
										input.Total_Amount_Not_Allocated = ifnull(input.Total_Amount_Received,0) - allocatedTotal;
										// Update allocation status
										if(ifnull(input.Total_Amount_Allocated,0) <= 0)
										{
											input.Payment_Receipt_Voucher_Status = "Unallocated";
										}
